-- Mod-authored Congress splash painting descriptions, pt_BR overlay.
-- Baseline in CivVAccess_CongressDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_MISSING"] = "Nenhuma descrição para esta imagem."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_LEAGUE_SPECIAL_SESSION_START_WORLD_CONGRESS"] =
    "Uma assembleia em sessão, vista do fundo do salão sobre as cabeças do público. Na frente, os delegados estão sentados ao redor de uma longa mesa coberta de vermelho sobre um estrado com tapete, com uma folha branca posta em cada lugar. Uma figura de vestes brancas e turbante branco está de pé na cabeceira da mesa para discursar ao salão, com um homem de barba escura ao seu lado. O público os enfrenta a partir de fileiras de cadeiras de madeira, turbantes e toucas e cabeças descobertas juntos. Mais espectadores assistem de entre pálidas colunas ao longo da parede direita."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_LEAGUE_PROJECT_WORLD_FAIR"] =
    "Uma gigantesca roda-gigante sobe para fora do topo do quadro pela direita, carros fechados para passageiros pendurados em sua borda. Sua base desce atrás de um grande arco de ferro verde rebitado, que transpõe uma parede pálida com a inscrição FERRIS WHEEL em letras. Os visitantes da feira cruzam o amplo calçadão poeirento abaixo: mulheres em longos vestidos, homens em sobretudos e chapéus-coco e cartolas. Baixos edifícios da feira com letreiros pintados alinham-se pelo caminho à esquerda, onde um salão branco com cúpula se ergue ao longe sob um céu azul pálido."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_LEAGUE_PROJECT_WORLD_GAMES"] =
    "Os primeiros passos de uma corrida: quatro corredores lançam-se para a frente da linha de saída, com a cabeça baixa, em uma pista escura que varre o primeiro plano. Atrás deles à esquerda, o juiz está de pé em um longo casaco branco, com a pistola erguida e ainda fumegando. As arquibancadas lotadas preenchem todo o fundo, a multidão pontilhada como manchas de cor. Postes de escada brancos e altos mastros alinham-se na beira da pista à direita, e o verde do campo se estende além deles."
